/* GameMaster offline cache. Generated by tools/build-offline.py from tools/sw.template.js: edit the template, not sw.js.

   Every page of the site is served from one cached copy of one version, so the Ledger, Council and Arbiter
   always match and the site keeps working without a connection. A new version downloads in the background
   and waits; the site offers "Update now" and only switches when someone taps it (or every tab is closed). */
const VERSION = '__VERSION__';
const CACHE = 'gamemaster-' + VERSION;
const FILES = __FILES__;

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('gamemaster-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', e => {
  if (e.data === 'update-now') self.skipWaiting();
  if (e.data === 'version' && e.source) e.source.postMessage({ type: 'version', version: VERSION });
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  e.respondWith(caches.open(CACHE).then(async c => {
    const hit = await c.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok && res.type === 'basic') c.put(req, res.clone());
      return res;
    } catch (err) {
      // offline and not cached: a page request falls back to the site's front door
      if (req.mode === 'navigate') { const home = await c.match('./'); if (home) return home; }
      throw err;
    }
  }));
});
